      for (const tx of [3, 6, 40, 44, 48, 52, 62, 66, 70, 74, 108, 112]) { const X = gx(tx), Y = FL - 88 - ((tx * 7) % 12); if (X > VW + 20 || X < -20) continue;   // headshots
        ctx.fillStyle = '#0a0c12'; ctx.fillRect(X, Y, 14, 18); ctx.fillStyle = '#d8d0c0'; ctx.fillRect(X + 1, Y + 1, 12, 16); ctx.fillStyle = ['#8a6a4a', '#4a3a2a', '#b08a56', '#2a2a30'][tx & 3]; ctx.fillRect(X + 4, Y + 4, 6, 6); ctx.fillStyle = '#3a4a6a'; ctx.fillRect(X + 2, Y + 11, 10, 6); }
      { const X = gx(30), Y = FL - 62; if (X > -140 && X < VW + 20) { ctx.fillStyle = '#1a2230'; ctx.fillRect(X - 3, Y - 4, 90, 54); for (let i = 0; i < 3; i++) for (let j = 0; j < 2; j++) crt(X + i * 29, Y + j * 25, 26, 22, i + j * 3); } }   // the monitor wall
      for (const tx of [4, 10, 29, 56, 62, 70, 96, 110]) { const X = gx(tx); if (X > -10 && X < VW + 10) chair(X, FL); }
      for (const [tx, h] of [[11, 52], [38, 60], [72, 58], [99, 54], [113, 58]]) { const X = gx(tx); if (X > -10 && X < VW + 10) { stand(X, FL, h); DD.art.glow(X, FL - h - 2, 36, '#ffe8a8', 0.14); DD.art.cone(X, FL - h, h, 20, '#ffe8a8', 0.06); } }
