        ctx.fillStyle = '#8a98b0'; ctx.fillRect(X, Y, W, 3); ctx.fillStyle = '#e8f0fa'; ctx.fillRect(X, Y, W, 1); ctx.fillStyle = '#2a3446'; ctx.fillRect(X, Y + 3, W, 1);
