      const T = Math.abs(Math.floor(s.T / 60)), tc = '00:' + String(Math.floor(T / 60) % 60).padStart(2, '0') + ':' + String(T % 60).padStart(2, '0');
      const M = MODE[s.mode], X = VW / 2 - 36;
