      ctx.fillStyle = M.col; const tri = (x, d) => { ctx.beginPath(); ctx.moveTo(x - d * 3, cyy - 3); ctx.lineTo(x + d * 3, cyy); ctx.lineTo(x - d * 3, cyy + 3); ctx.fill(); };
      if (rate > 0) { tri(X + 8, 1); if (Math.abs(rate) > 1) tri(X + 14, 1); } else { tri(X + 8, -1); tri(X + 14, -1); }
      DD.text(M.name + (s.ghost ? ' REVERSE' : ''), X + 20, 16, M.col, 1, null);
      if (s.modeT > 0) { ctx.fillStyle = '#243040'; ctx.fillRect(X + 4, 23, 64, 1); ctx.fillStyle = M.col; ctx.fillRect(X + 4, 23, Math.round(64 * s.modeT / 420), 1); }
